mapper.select:
SELECT *
FROM yan_knowledge_document
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
LIMIT 1

mapper.update:
UPDATE yan_knowledge_document
SET current_version_id = #{versionId}, update_time = NOW(3)
WHERE id = #{documentId}
  AND NOT EXISTS (
    SELECT 1
    FROM yan_knowledge_document_version
    WHERE document_id = #{documentId}
      AND version_no > (
        SELECT version_no
        FROM yan_knowledge_document_version
        WHERE id = #{versionId}
      )
  )

UPDATE yan_knowledge_document
SET current_version_id = NULL, update_time = NOW(3)
WHERE id = #{documentId}
  AND current_version_id = #{versionId}
